<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Self‑Steering Snake</title>
<style>
  body{margin:0;background:#111;color:#0f0;font-family:monospace;}
  #score{position:absolute;top:5px;left:5px;font-size:18px;}
  canvas{display:block;margin:auto;background:#000;}
</style>
</head>
<body>
<div id="score">Score: 0</div>
<canvas id="game" width="400" height="400"></canvas>
<script>
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const gridSize=20,boardSize=20;
const snakeInitial=[{x:10,y:10},{x:9,y:10},{x:8,y:10}];
let snake=snakeInitial.slice();
let food=null;
let score=0;
let gameInterval=null;

function randomCell() {
  let x=Math.floor(Math.random()*boardSize);
  let y=Math.floor(Math.random()*boardSize);
  return {x,y};
}

function placeFood() {
  let cell;
  while (true) {
    cell=randomCell();
    if (!snake.some(seg=>seg.x===cell.x && seg.y===cell.y)) break;
  }
  food=cell;
}

function distance(a,b) {
  return Math.abs(a.x-b.x)+Math.abs(a.y-b.y);
}

function getValidMoves() {
  const head=snake[0];
  const dirs=[{dx:0,dy:-1},{dx:0,dy:1},{dx:-1,dy:0},{dx:1,dy:0}];
  const moves=[];
  const tail=snake[snake.length-1];
  for (const d of dirs) {
    const nx=head.x+d.dx, ny=head.y+d.dy;
    if (nx<0||nx>=boardSize||ny<0||ny>=boardSize) continue;
    const newHead={x:nx,y:ny};
    const isEating=newHead.x===food.x && newHead.y===food.y;
    // collision test
    let collides=false;
    for (let i=0;i<snake.length;i++) {
      const seg=snake[i];
      if (newHead.x===seg.x && newHead.y===seg.y) {
        if (isEating && seg===tail) {collides=true;break;}
        if (!isEating && seg===tail) continue;
        collides=true;break;
      }
    }
    if (!collides) moves.push({dx:d.dx,dy:d.dy,dist:distance(newHead,food)});
  }
  return moves;
}

function gameTick() {
  const moves=getValidMoves();
  if (moves.length===0) {clearInterval(gameInterval);return;}
  moves.sort((a,b)=>a.dist-b.dist);
  const {dx,dy}=moves[0];
  const newHead={x:snake[0].x+dx,y:snake[0].y+dy};
  const isEating=newHead.x===food.x && newHead.y===food.y;
  snake.unshift(newHead);
  if (isEating) {score++; document.getElementById('score').innerText='Score: '+score; placeFood();}
  else snake.pop();
  render();
}

function render() {
  ctx.fillStyle='#000';ctx.fillRect(0,0,canvas.width,canvas.height);
  // draw food
  ctx.fillStyle='#f00';
  ctx.fillRect(food.x*gridSize,food.y*gridSize,gridSize,gridSize);
  // draw snake
  ctx.fillStyle='#0f0';
  for (const seg of snake) ctx.fillRect(seg.x*gridSize,seg.y*gridSize,gridSize,gridSize);
}

function start() {
  snake=snakeInitial.slice();
  score=0;document.getElementById('score').innerText='Score: 0';
  placeFood();
  render();
  clearInterval(gameInterval);
  gameInterval=setInterval(gameTick,200);
}
start();
</script>
</body>
</html>
```
The script runs a canvas snake that automatically chooses the shortest non‑colliding path toward the food each tick, growing and scoring as it eats.
